/*
 Pebble agent UDP reuseport selector

 Approach:
 - Compute a single target slot via fast range reduction of reuse->hash.
 - Avoid loops and extra helper calls; the kernel only honors the first
   select attempt, so additional calls waste cycles and raise tail latency.
 - Clamp active to [1,128]; fall back to SK_PASS to preserve kernel behavior.

 Why it should help:
 - Fewer instructions than a 128-iteration unrolled probe loop.
 - No expensive modulo in the general case (use 32x32->64 multiply-high).
 - Lower I-cache pressure and fewer branches help p99 under high load.
*/
 //go:build ignore

#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

struct {
    __uint(type, BPF_MAP_TYPE_REUSEPORT_SOCKARRAY);
    __uint(max_entries, 128);
    __type(key, __u32);
    __type(value, __u32);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_udp_targets SEC(".maps");

struct agent_state {
    __u32 active;
    __u32 pad;
};

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct agent_state);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_agent_state SEC(".maps");

/* EVOLVE-BLOCK-START
   Agent UDP reuseport selector (single-shot, low-latency)

   Rationale:
   - The kernel honors only the first successful bpf_sk_select_reuseport call.
     Extra attempts are ignored and just burn cycles.
   - Derive the slot from reuse->hash with fast range reduction:
       * power-of-two active: bitmask
       * otherwise: 32x32->64 multiply and take high 32 bits (avoid modulo)
   - Clamp active to [1,128]; on any issue, return SK_PASS for kernel default.
*/
SEC("sk_reuseport/selector")
enum sk_action agent_udp_selector(struct sk_reuseport_md *reuse)
{
    __u32 key = 0;
    struct agent_state *st = bpf_map_lookup_elem(&pebble_agent_state, &key);
    if (!st)
        return SK_PASS;

    __u32 active = st->active;
    if (active == 0)
        return SK_PASS;
    if (active > 128)
        active = 128;

    __u32 slot;
    if ((active & (active - 1)) == 0) {
        // Power-of-two fast path
        slot = reuse->hash & (active - 1);
    } else {
        // General case: fast range reduction without modulo
        __u64 prod = (__u64)reuse->hash * active;
        slot = (__u32)(prod >> 32);
    }

    // Single selection attempt; fallback handled by returning SK_PASS.
    bpf_sk_select_reuseport(reuse, &pebble_udp_targets, &slot, 0);
    return SK_PASS;
}
// EVOLVE-BLOCK-END

char _license[] SEC("license") = "GPL";

